-- IPL management schema
-- Select the ipl_management database before running this file.
-- AUTO_INCREMENT is retained for IDs generated by the application.

CREATE TABLE venues (
    venue_id INT AUTO_INCREMENT PRIMARY KEY,
    venue_name VARCHAR(150) NOT NULL UNIQUE,
    city VARCHAR(100) NOT NULL,
    country VARCHAR(100) NOT NULL,
    capacity INT,
    pitch_type VARCHAR(50),
    established_year INT,
    CHECK (capacity IS NULL OR capacity >= 0)
);

CREATE TABLE seasons (
    season_id INT AUTO_INCREMENT PRIMARY KEY,
    season_year INT NOT NULL UNIQUE,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    host_country VARCHAR(100) NOT NULL,
    total_teams INT,
    total_matches INT,
    CHECK (end_date > start_date),
    CHECK (total_teams IS NULL OR total_teams > 0),
    CHECK (total_matches IS NULL OR total_matches > 0)
);

CREATE TABLE teams (
    team_id INT AUTO_INCREMENT PRIMARY KEY,
    team_name VARCHAR(150) NOT NULL UNIQUE,
    short_name VARCHAR(10) NOT NULL UNIQUE,
    city VARCHAR(100) NOT NULL,
    home_venue_id INT,
    coach VARCHAR(100),
    jersey_color VARCHAR(50),
    founded_year INT,
    titles_won INT NOT NULL,
    FOREIGN KEY (home_venue_id) REFERENCES venues(venue_id),
    CHECK (founded_year IS NULL OR founded_year > 0),
    CHECK (titles_won >= 0)
);

CREATE TABLE players (
    player_id INT AUTO_INCREMENT PRIMARY KEY,
    player_name VARCHAR(150) NOT NULL,
    dob DATE,
    nationality VARCHAR(100),
    role VARCHAR(30) NOT NULL,
    batting_style VARCHAR(20),
    bowling_style VARCHAR(100),
    team_id INT,
    jersey_no INT,
    matches_played INT,
    runs_scored INT,
    wickets_taken INT,
    base_price NUMERIC(10, 2),
    is_active INT NOT NULL,
    FOREIGN KEY (team_id) REFERENCES teams(team_id),
    CHECK (role IN ('Batsman', 'Bowler', 'All-Rounder', 'Wicket-Keeper')),
    CHECK (batting_style IS NULL OR batting_style IN ('Right-Hand', 'Left-Hand')),
    CHECK (jersey_no IS NULL OR jersey_no BETWEEN 0 AND 99),
    CHECK (matches_played IS NULL OR matches_played >= 0),
    CHECK (runs_scored IS NULL OR runs_scored >= 0),
    CHECK (wickets_taken IS NULL OR wickets_taken >= 0),
    CHECK (base_price IS NULL OR base_price >= 0),
    CHECK (is_active IN (0, 1))
);

CREATE TABLE matches (
    match_id INT AUTO_INCREMENT PRIMARY KEY,
    season_id INT NOT NULL,
    venue_id INT NOT NULL,
    team1_id INT NOT NULL,
    team2_id INT NOT NULL,
    match_date DATE NOT NULL,
    match_time TIME,
    match_type VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL,
    winner_id INT,
    toss_winner_id INT,
    toss_decision VARCHAR(10),
    win_margin INT,
    win_type VARCHAR(20),
    player_of_match INT,
    FOREIGN KEY (season_id) REFERENCES seasons(season_id),
    FOREIGN KEY (venue_id) REFERENCES venues(venue_id),
    FOREIGN KEY (team1_id) REFERENCES teams(team_id),
    FOREIGN KEY (team2_id) REFERENCES teams(team_id),
    FOREIGN KEY (winner_id) REFERENCES teams(team_id),
    FOREIGN KEY (toss_winner_id) REFERENCES teams(team_id),
    FOREIGN KEY (player_of_match) REFERENCES players(player_id),
    CHECK (team1_id <> team2_id),
    CHECK (match_type IN ('League', 'Qualifier', 'Eliminator', 'Final', 'Super Over')),
    CHECK (status IN ('Scheduled', 'Live', 'Completed', 'Cancelled', 'No Result')),
    CHECK (toss_decision IS NULL OR toss_decision IN ('Bat', 'Bowl')),
    CHECK (win_margin IS NULL OR win_margin >= 0),
    CHECK (win_type IS NULL OR win_type IN ('Runs', 'Wickets', 'Super Over', 'No Result'))
);

CREATE TABLE player_match (
    id INT AUTO_INCREMENT PRIMARY KEY,
    match_id INT NOT NULL,
    player_id INT NOT NULL,
    team_id INT NOT NULL,
    runs_scored INT NOT NULL,
    balls_faced INT NOT NULL,
    fours INT,
    sixes INT,
    wickets_taken INT,
    overs_bowled NUMERIC(4, 1),
    runs_conceded INT,
    catches INT,
    stumpings INT,
    is_out INT NOT NULL,
    UNIQUE (match_id, player_id),
    FOREIGN KEY (match_id) REFERENCES matches(match_id),
    FOREIGN KEY (player_id) REFERENCES players(player_id),
    FOREIGN KEY (team_id) REFERENCES teams(team_id),
    CHECK (runs_scored >= 0),
    CHECK (balls_faced >= 0),
    CHECK (fours IS NULL OR fours >= 0),
    CHECK (sixes IS NULL OR sixes >= 0),
    CHECK (wickets_taken IS NULL OR wickets_taken >= 0),
    CHECK (overs_bowled IS NULL OR overs_bowled >= 0),
    CHECK (runs_conceded IS NULL OR runs_conceded >= 0),
    CHECK (catches IS NULL OR catches >= 0),
    CHECK (stumpings IS NULL OR stumpings >= 0),
    CHECK (is_out IN (0, 1))
);

CREATE VIEW v_match_details AS
SELECT
    m.match_id,
    m.match_date,
    m.match_time,
    m.match_type,
    m.status,
    m.win_margin,
    m.win_type,
    s.season_year,
    v.venue_name,
    v.city AS venue_city,
    t1.team_name AS team1_name,
    t1.short_name AS team1_short,
    t2.team_name AS team2_name,
    t2.short_name AS team2_short,
    w.team_name AS winner_name,
    p.player_name AS player_of_match_name
FROM matches m
JOIN seasons s ON m.season_id = s.season_id
JOIN venues v ON m.venue_id = v.venue_id
JOIN teams t1 ON m.team1_id = t1.team_id
JOIN teams t2 ON m.team2_id = t2.team_id
LEFT JOIN teams w ON m.winner_id = w.team_id
LEFT JOIN players p ON m.player_of_match = p.player_id;
